import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const CreateLesson = () => {
    const navigate = useNavigate();
    const [specialties, setSpecialties] = useState([]);
    const [courses, setCourses] = useState([]);
    const [groups, setGroups] = useState([]);
    const [periods, setPeriods] = useState([]);
    const [classrooms, setClassrooms] = useState([]);
    const [weekDays, setWeekDays] = useState([]);

    const [selectedSpecialty, setSelectedSpecialty] = useState("");
    const [selectedCourse, setSelectedCourse] = useState("");
    const [selectedGroup, setSelectedGroup] = useState("");
    const [subject, setSubject] = useState("");
    const [teacher, setTeacher] = useState("");
    const [lessonType, setLessonType] = useState("");
    const [selectedPeriod, setSelectedPeriod] = useState("");
    const [selectedClassroom, setSelectedClassroom] = useState("");
    const [selectedWeekDay, setSelectedWeekDay] = useState("");

    useEffect(() => {
        const fetchSpecialties = async () => {
            try {
                const response = await axios.get("/specialties");
                setSpecialties(response.data);
            } catch (error) {
                console.error("Ошибка загрузки специальностей:", error);
            }
        };
        fetchSpecialties();
    }, []);

    useEffect(() => {
        const fetchPeriods = async () => {
            try {
                const response = await axios.get("/api/periods");
                setPeriods(response.data);
            } catch (error) {
                console.error("Ошибка загрузки времени пар:", error);
            }
        };
        fetchPeriods();
    }, []);

    useEffect(() => {
        const fetchClassrooms = async () => {
            try {
                const token = localStorage.getItem("token");
                if (!token) {
                    console.error("Нет токена авторизации");
                    return;
                }
                const response = await axios.get("/api/rooms", {
                    headers: { Authorization: `Bearer ${token}` },
                });
                setClassrooms(response.data);
            } catch (error) {
                console.error("Ошибка загрузки кабинетов:", error);
            }
        };
        fetchClassrooms();
    }, []);

    useEffect(() => {
        const fetchWeekDays = async () => {
            try {
                const response = await axios.get("/api/weekdays");
                setWeekDays(response.data);
            } catch (error) {
                console.error("Ошибка загрузки дней недели:", error);
            }
        };
        fetchWeekDays();
    }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            const token = localStorage.getItem("token");
            await axios.post(
                "/schedule",
                { subject, teacher, lessonType, period: selectedPeriod, group: selectedGroup, classroom: selectedClassroom, weekDay: selectedWeekDay },
                { headers: { Authorization: `Bearer ${token}` } }
            );
            alert("Пара успешно добавлена!");
            navigate("/dashboard");
        } catch (error) {
            console.error("Ошибка при добавлении пары:", error);
            alert("Ошибка при добавлении пары");
        }
    };

    return (
        <div>
            <h2>Добавить новую пару</h2>
            <form onSubmit={handleSubmit}>
                <label>Специальность:</label>
                <select value={selectedSpecialty} onChange={(e) => setSelectedSpecialty(e.target.value)} required>
                    <option value="">Выберите специальность</option>
                    {specialties.map((spec) => (
                        <option key={spec._id} value={spec._id}>{spec.name}</option>
                    ))}
                </select>

                <label>Курс:</label>
                <select value={selectedCourse} onChange={(e) => setSelectedCourse(e.target.value)} required disabled={!selectedSpecialty}>
                    <option value="">Выберите курс</option>
                    {courses.map((course) => (
                        <option key={course._id} value={course._id}>{course.name}</option>
                    ))}
                </select>

                <label>Группа:</label>
                <select value={selectedGroup} onChange={(e) => setSelectedGroup(e.target.value)} required disabled={!selectedCourse}>
                    <option value="">Выберите группу</option>
                    {groups.map((group) => (
                        <option key={group._id} value={group._id}>{group.name}</option>
                    ))}
                </select>

                <label>День недели:</label>
                <select value={selectedWeekDay} onChange={(e) => setSelectedWeekDay(e.target.value)} required>
                    <option value="">Выберите день недели</option>
                    {weekDays.map((day) => (
                        <option key={day.id} value={day.id}>{day.name}</option>
                    ))}
                </select>

                <label>Название предмета:</label>
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} required />

                <label>Преподаватель:</label>
                <input type="text" value={teacher} onChange={(e) => setTeacher(e.target.value)} required />

                <label>Тип пары:</label>
                <select value={lessonType} onChange={(e) => setLessonType(e.target.value)} required>
                    <option value="">Выберите тип пары</option>
                    <option value="Лекция">Лекция</option>
                    <option value="Практика">Практика</option>
                    <option value="Лабораторная">Лабораторная</option>
                    <option value="Экзамен">Экзамен</option>
                    <option value="Учебная практика">Учебная практика</option>
                    <option value="Выездная практика">Выездная практика</option>
                </select>

                <button type="submit">Добавить пару</button>
            </form>
        </div>
    );
};

export default CreateLesson;
